{"path": "poker.py", "content": "from collections import Counter

RANKS = {r: i for i, r in enumerate("23456789", 2)}
RANKS.update({"10": 10, "T": 10, "J": 11, "Q": 12, "K": 13, "A": 14})


def _score(hand):
    cards = hand.split()
    values = [RANKS[c[:-1]] for c in cards]
    suits = [c[-1] for c in cards]
    counts = Counter(values)
    # Sort by count, then value, descending
    groups = sorted(counts.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    shape = [c for _, c in groups]
    ordered = [v for v, _ in groups]

    flush = len(set(suits)) == 1
    uniq = sorted(set(values))
    straight = len(uniq) == 5 and uniq[-1] - uniq[0] == 4
    if uniq == [2, 3, 4, 5, 14]:
        straight = True
        ordered = [5, 4, 3, 2, 1]

    if straight and flush:
        cat = 8
    elif shape == [4, 1]:
        cat = 7
    elif shape == [3, 2]:
        cat = 6
    elif flush:
        cat = 5
    elif straight:
        cat = 4
    elif shape == [3, 1, 1]:
        cat = 3
    elif shape == [2, 2, 1]:
        cat = 2
    elif shape == [2, 1, 1, 1]:
        cat = 1
    else:
        cat = 0
    return (cat, ordered)


def best_hands(hands):
    scores = [_score(h) for h in hands]
    best = max(scores)
    return [h for h, s in zip(hands, scores) if s == best]
"}

